#include <bits/stdc++.h>
using namespace std;

struct CharPair {
    char chr;
    int value;
    int idx;
    CharPair(char c, int v, int i) : chr(c), value(v), idx(i) {}
};

void swapChars(vector<char>& chArr, vector<int>& vals, int i) {
    char temp = chArr[i];
    chArr[i] = chArr[(int)chArr.size() - i - 1];
    chArr[(int)chArr.size() - i - 1] = temp;

    int tempVal = vals[i];
    vals[i] = vals[(int)vals.size() - i - 1];
    vals[(int)vals.size() - i - 1] = tempVal;
}

bool isAntiPalindromic(const vector<char>& chArr) {
    int len = (int)chArr.size();
    for (int i = 0; i < len / 2; i++) {
        if (chArr[i] == chArr[len - i - 1]) {
            return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cin.ignore();
    string s;
    getline(cin, s);
    s = s.substr(0, s.find_last_not_of(" \n\r\t") + 1);
    vector<char> chArr(s.begin(), s.end());
    vector<int> vals(n);
    for (int i = 0; i < n; i++) {
        cin >> vals[i];
    }
    cin.ignore();

    vector<CharPair> mismatchChars;
    vector<CharPair> pairList;
    for (int i = 0; i < n / 2; i++) {
        if (vals[i] > vals[n - i - 1]) {
            swapChars(chArr, vals, i);
        }
        CharPair cp(chArr[i], vals[i], i);
        if (chArr[i] == chArr[n - i - 1]) {
            mismatchChars.push_back(cp);
        }
        pairList.push_back(cp);
    }

    std::sort(pairList.begin(), pairList.end(), [](const CharPair& a, const CharPair& b) {
        return a.value < b.value;
    });

    int diffSum = 0;
    if (!isAntiPalindromic(chArr)) {
        if (mismatchChars.size() == 1) {
            CharPair wrong = mismatchChars[0];
            for (const auto& cp : pairList) {
                if (cp.chr != wrong.chr && chArr[n - cp.idx - 1] != wrong.chr) {
                    diffSum = wrong.value + cp.value;
                    break;
                }
            }
        } else if (mismatchChars.size() > 1) {
            std::unordered_map<char, int> countMap;
            for (const auto& cp : mismatchChars) {
                countMap[cp.chr]++;
            }
            int maxCount = 0;
            for (const auto& kv : countMap) {
                if (kv.second > maxCount) maxCount = kv.second;
            }
            vector<CharPair> appendList;
            while (maxCount * 2 > (int)mismatchChars.size() + (int)appendList.size()) {
                auto maxEntry = std::max_element(countMap.begin(), countMap.end(),
                    [](const pair<char,int>& a, const pair<char,int>& b) {
                        return a.second < b.second;
                    });
                char maxChar = maxEntry->first;
                for (const auto& cp : pairList) {
                    if (cp.chr != maxChar && chArr[n - cp.idx - 1] != maxChar && 
                        find_if(mismatchChars.begin(), mismatchChars.end(), [&](const CharPair& c){ return c.idx == cp.idx; }) == mismatchChars.end() &&
                        find_if(appendList.begin(), appendList.end(), [&](const CharPair& c){ return c.idx == cp.idx; }) == appendList.end()) {
                        appendList.push_back(cp);
                        break;
                    }
                }
                countMap[maxChar]--;
                if (countMap[maxChar] == 0) {
                    countMap.erase(maxChar);
                }
                maxCount = 0;
                for (const auto& kv : countMap) {
                    if (kv.second > maxCount) maxCount = kv.second;
                }
            }
            int sumMismatch = 0;
            for (const auto& c : mismatchChars) sumMismatch += c.value;
            int sumAppend = 0;
            for (const auto& c : appendList) sumAppend += c.value;
            diffSum = sumMismatch + sumAppend;
        }
    }
    int totalSum = std::accumulate(vals.begin(), vals.end(), 0);
    cout << totalSum - diffSum << "\n";

    return 0;
}
